    10	public class Database {
    11	    private static final Logger logger = LoggerFactory.getLogger(Database.class);
    12	    private final String url;
    13	    private final String user;
    14	    private final String password;
    15	
    16	    public Database() {
    17	        this.url = System.getenv("DB_URL");
    18	        this.user = System.getenv("DB_USER");
    19	        this.password = System.getenv("DB_PASSWORD");
    20	
    21	        if (url == null || user == null || password == null) {
    22	            throw new RuntimeException("Missing required environment variables: DB_URL, DB_USER, DB_PASSWORD");
    23	        }
    24	    }
    25	
    26	    public void initialize() {
    27	        try (Connection conn = getConnection()) {
    28	            createTables(conn);
    29	            logger.info("Database initialized successfully");
    30	        } catch (SQLException e) {
    31	            logger.error("Failed to initialize database", e);
    32	            throw new RuntimeException("Database initialization failed", e);
    33	        }
    34	    }
    35	
    36	    public Connection getConnection() throws SQLException {
    37	        return DriverManager.getConnection(url, user, password);
    38	    }
    39	
    40	    private void createTables(Connection conn) throws SQLException {
    41	        var stmt = conn.createStatement();
    42	
    43	        // Messages table
    44	        stmt.execute("""
    45	            CREATE TABLE IF NOT EXISTS messages (
    46	                id SERIAL PRIMARY KEY,
    47	                channel VARCHAR(50) NOT NULL,
    48	                to_address VARCHAR(255) NOT NULL,
    49	                subject VARCHAR(255) NOT NULL,
    50	                body TEXT NOT NULL
    51	            )
    52	        """);
    53	
    54	        // Reservations table
    55	        stmt.execute("""
    56	            CREATE TABLE IF NOT EXISTS reservations (
    57	                id SERIAL PRIMARY KEY,
    58	                room_number INTEGER NOT NULL,
    59	                guest_name VARCHAR(255) NOT NULL,
    60	                guest_email VARCHAR(255) NOT NULL,
    61	                guest_cpf VARCHAR(14),
    62	                company_cnpj VARCHAR(18),
    63	                company_name VARCHAR(255),
    64	                guest_passport VARCHAR(50),
    65	                guest_country VARCHAR(100),
    66	                check_in DATE NOT NULL,
    67	                check_out DATE NOT NULL,
    68	                guests INTEGER NOT NULL,
    69	                rate_plan VARCHAR(50) NOT NULL,
    70	                nights INTEGER NOT NULL,
    71	                subtotal NUMERIC(10,2) NOT NULL,
    72	                discount NUMERIC(10,2) NOT NULL,
    73	                total NUMERIC(10,2) NOT NULL,
    74	                status VARCHAR(50) NOT NULL,
    75	                amount_paid NUMERIC(10,2) NOT NULL DEFAULT 0,
    76	                refund NUMERIC(10,2)
    77	            )
    78	        """);
    79	
    80	        stmt.close();
    81	    }
    82	}
