    13	public class ReservationService {
    14	    private static final Logger logger = LoggerFactory.getLogger(ReservationService.class);
    15	    private final Database database;
    16	
    17	    public ReservationService(Database database) {
    18	        this.database = database;
    19	    }
    20	
    21	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    22	                                        String guestCpf, String companyCnpj, String companyName,
    23	                                        String guestPassport, String guestCountry,
    24	                                        LocalDate checkIn, LocalDate checkOut, int guests,
    25	                                        RatePlan ratePlan) throws SQLException {
    26	
    27	        RoomType roomType = getRoomType(roomNumber);
    28	        if (roomType == null) {
    29	            throw new ApiException("ROOM_NOT_FOUND", "Room not found", 404);
    30	        }
    31	
    32	        if (guests < 1 || guests > roomType.capacity) {
    33	            throw new ApiException("CAPACITY_EXCEEDED", "Guest count exceeds room capacity", 422);
    34	        }
    35	
    36	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    37	            throw new ApiException("INVALID_REQUEST", "Check-out must be after check-in", 400);
    38	        }
    39	
    40	        if (isRoomBooked(roomNumber, checkIn, checkOut)) {
    41	            throw new ApiException("ROOM_UNAVAILABLE", "Room is not available for selected dates", 409);
    42	        }
    43	
    44	        int nights = PricingService.getNights(checkIn, checkOut);
    45	        double subtotal = PricingService.calculateSubtotal(roomType, checkIn, checkOut);
    46	        double discount = PricingService.calculateDiscount(ratePlan, subtotal);
    47	        double total = PricingService.calculateTotal(subtotal, discount);
    48	
    49	        try (Connection conn = database.getConnection()) {
    50	            var stmt = conn.prepareStatement("""
    51	                INSERT INTO reservations (room_number, guest_name, guest_email,
    52	                    guest_cpf, company_cnpj, company_name, guest_passport, guest_country,
    53	                    check_in, check_out, guests, rate_plan, nights, subtotal, discount,
    54	                    total, status, amount_paid)
    55	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    56	                """, java.sql.Statement.RETURN_GENERATED_KEYS);
    57	
    58	            stmt.setInt(1, roomNumber);
    59	            stmt.setString(2, guestName);
    60	            stmt.setString(3, guestEmail);
    61	            stmt.setString(4, guestCpf);
    62	            stmt.setString(5, companyCnpj);
    63	            stmt.setString(6, companyName);
    64	            stmt.setString(7, guestPassport);
    65	            stmt.setString(8, guestCountry);
    66	            stmt.setDate(9, java.sql.Date.valueOf(checkIn));
    67	            stmt.setDate(10, java.sql.Date.valueOf(checkOut));
    68	            stmt.setInt(11, guests);
    69	            stmt.setString(12, ratePlan.value);
    70	            stmt.setInt(13, nights);
    71	            stmt.setBigDecimal(14, new java.math.BigDecimal(subtotal));
    72	            stmt.setBigDecimal(15, new java.math.BigDecimal(discount));
    73	            stmt.setBigDecimal(16, new java.math.BigDecimal(total));
    74	            stmt.setString(17, ReservationStatus.PENDING.value);
    75	            stmt.setBigDecimal(18, new java.math.BigDecimal(0));
    76	
    77	            stmt.executeUpdate();
    78	
    79	            ResultSet rs = stmt.getGeneratedKeys();
    80	            if (rs.next()) {
    81	                int id = rs.getInt(1);
    82	                return getReservationById(id);
    83	            }
    84	        }
    85	
    86	        throw new RuntimeException("Failed to create reservation");
    87	    }
