    89	    public Reservation getReservationById(int id) throws SQLException {
    90	        try (Connection conn = database.getConnection()) {
    91	            var stmt = conn.prepareStatement(
    92	                "SELECT * FROM reservations WHERE id = ?");
    93	            stmt.setInt(1, id);
    94	
    95	            ResultSet rs = stmt.executeQuery();
    96	            if (rs.next()) {
    97	                return mapReservation(rs);
    98	            }
    99	        }
   100	
   101	        throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
   102	    }
   103	
   104	    public Reservation confirmReservation(int id, double amountPaid) throws SQLException {
   105	        Reservation reservation = getReservationById(id);
   106	
   107	        if (reservation.status != ReservationStatus.PENDING) {
   108	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only confirm pending reservations", 409);
   109	        }
   110	
   111	        try (Connection conn = database.getConnection()) {
   112	            var stmt = conn.prepareStatement(
   113	                "UPDATE reservations SET status = ?, amount_paid = ? WHERE id = ?");
   114	            stmt.setString(1, ReservationStatus.CONFIRMED.value);
   115	            stmt.setBigDecimal(2, new java.math.BigDecimal(amountPaid));
   116	            stmt.setInt(3, id);
   117	            stmt.executeUpdate();
   118	
   119	            sendConfirmationEmail(reservation, amountPaid);
   120	        }
   121	
   122	        return getReservationById(id);
   123	    }
   124	
   125	    public Reservation cancelReservation(int id) throws SQLException {
   126	        Reservation reservation = getReservationById(id);
   127	
   128	        if (reservation.status == ReservationStatus.CHECKED_OUT ||
   129	            reservation.status == ReservationStatus.CANCELLED) {
   130	            throw new ApiException("OPERATION_NOT_ALLOWED", "Cannot cancel this reservation", 409);
   131	        }
   132	
   133	        double refund = 0;
   134	        if (reservation.status == ReservationStatus.CONFIRMED) {
   135	            if (reservation.ratePlan == RatePlan.STANDARD) {
   136	                refund = reservation.amountPaid;
   137	            }
   138	        }
   139	
   140	        try (Connection conn = database.getConnection()) {
   141	            var stmt = conn.prepareStatement(
   142	                "UPDATE reservations SET status = ?, refund = ? WHERE id = ?");
   143	            stmt.setString(1, ReservationStatus.CANCELLED.value);
   144	            stmt.setBigDecimal(2, refund > 0 ? new java.math.BigDecimal(refund) : null);
   145	            stmt.setInt(3, id);
   146	            stmt.executeUpdate();
   147	        }
   148	
   149	        return getReservationById(id);
   150	    }
   151	
   152	    public Reservation checkIn(int id) throws SQLException {
   153	        Reservation reservation = getReservationById(id);
