   180	            stmt.setString(1, ReservationStatus.CHECKED_OUT.value);
   181	            stmt.setInt(2, id);
   182	            stmt.executeUpdate();
   183	        }
   184	
   185	        return getReservationById(id);
   186	    }
   187	
   188	    private Reservation mapReservation(ResultSet rs) throws SQLException {
   189	        return new Reservation(
   190	            rs.getInt("id"),
   191	            rs.getInt("room_number"),
   192	            rs.getString("guest_name"),
   193	            rs.getString("guest_email"),
   194	            rs.getString("guest_cpf"),
   195	            rs.getString("company_cnpj"),
   196	            rs.getString("company_name"),
   197	            rs.getString("guest_passport"),
   198	            rs.getString("guest_country"),
   199	            rs.getDate("check_in").toLocalDate(),
   200	            rs.getDate("check_out").toLocalDate(),
   201	            rs.getInt("guests"),
   202	            RatePlan.fromString(rs.getString("rate_plan")),
   203	            rs.getInt("nights"),
   204	            rs.getDouble("subtotal"),
   205	            rs.getDouble("discount"),
   206	            rs.getDouble("total"),
   207	            ReservationStatus.fromString(rs.getString("status")),
   208	            rs.getDouble("amount_paid"),
   209	            rs.getObject("refund") != null ? rs.getDouble("refund") : null
   210	        );
   211	    }
   212	
   213	    private RoomType getRoomType(int roomNumber) {
   214	        return switch (roomNumber) {
   215	            case 101, 102 -> RoomType.STANDARD;
   216	            case 201, 202 -> RoomType.DELUXE;
   217	            case 301 -> RoomType.SUITE;
   218	            default -> null;
   219	        };
   220	    }
   221	
   222	    private boolean isRoomBooked(int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
   223	        try (Connection conn = database.getConnection()) {
   224	            var stmt = conn.prepareStatement("""
   225	                SELECT COUNT(*) FROM reservations
   226	                WHERE room_number = ?
   227	                  AND status != ?
   228	                  AND check_in < ?
   229	                  AND check_out > ?
   230	                """);
   231	            stmt.setInt(1, roomNumber);
   232	            stmt.setString(2, ReservationStatus.CANCELLED.value);
   233	            stmt.setDate(3, java.sql.Date.valueOf(checkOut));
   234	            stmt.setDate(4, java.sql.Date.valueOf(checkIn));
   235	
   236	            ResultSet rs = stmt.executeQuery();
   237	            if (rs.next()) {
   238	                return rs.getInt(1) > 0;
   239	            }
   240	        }
   241	        return false;
   242	    }
