   244	    private void sendConfirmationEmail(Reservation reservation, double amountPaid) throws SQLException {
   245	        RoomType roomType = getRoomType(reservation.roomNumber);
   246	        Document document = DocumentService.generateDocument(reservation, roomType);
   247	
   248	        String body = "Olá, " + reservation.guestName + "!\n\n" +
   249	                     "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   250	                     document.text + "\n\n" +
   251	                     "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   252	                     "Até breve!";
   253	
   254	        saveMessage("EMAIL", reservation.guestEmail, "Reserva confirmada - Pousada Maré Alta", body);
   255	    }
