     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PricingService {
     9	
    10	    public static double calculateNightlyPrice(double baseRate, LocalDate date) {
    11	        if (isHighSeason(date)) {
    12	            return round(baseRate * 1.20);
    13	        }
    14	        return baseRate;
    15	    }
    16	
    17	    private static boolean isHighSeason(LocalDate date) {
    18	        Month month = date.getMonth();
    19	        int day = date.getDayOfMonth();
    20	
    21	        // Julho
    22	        if (month == Month.JULY) {
    23	            return true;
    24	        }
    25	
    26	        // 15 de dezembro até fim de fevereiro
    27	        if (month == Month.DECEMBER && day >= 15) {
    28	            return true;
    29	        }
    30	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    31	            return true;
    32	        }
    33	
    34	        return false;
    35	    }
    36	
    37	    public static double calculateSubtotal(RoomType roomType, LocalDate checkIn, LocalDate checkOut) {
    38	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    39	        double subtotal = 0.0;
    40	
    41	        for (int i = 0; i < nights; i++) {
    42	            LocalDate nightDate = checkIn.plusDays(i);
    43	            double nightlyPrice = calculateNightlyPrice(roomType.nightlyRate, nightDate);
    44	            subtotal += nightlyPrice;
    45	        }
    46	
    47	        return round(subtotal);
    48	    }
    49	
    50	    public static double calculateDiscount(RatePlan ratePlan, double subtotal) {
    51	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    52	            return round(subtotal * 0.15);
    53	        }
    54	        return 0.0;
    55	    }
    56	
    57	    public static double calculateTotal(double subtotal, double discount) {
    58	        return round(subtotal - discount);
    59	    }
    60	
    61	    public static double round(double value) {
    62	        BigDecimal bd = new BigDecimal(value);
    63	        return bd.setScale(2, RoundingMode.HALF_EVEN).doubleValue();
    64	    }
    65	
    66	    public static int getNights(LocalDate checkIn, LocalDate checkOut) {
    67	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    68	    }
    69	}
