261	package com.pousadamarealta;
262	
263	import java.math.BigDecimal;
264	import java.math.RoundingMode;
265	import java.time.LocalDate;
266	import java.time.Month;
267	
268	public class PricingService {
269	
270	    public static double calculateNightlyPrice(double baseRate, LocalDate date) {
271	        if (isHighSeason(date)) {
272	            return round(baseRate * 1.20);
273	        }
274	        return baseRate;
275	    }
276	
277	    private static boolean isHighSeason(LocalDate date) {
278	        Month month = date.getMonth();
279	        int day = date.getDayOfMonth();
280	
281	        // Julho
282	        if (month == Month.JULY) {
283	            return true;
284	        }
285	
286	        // 15 de dezembro até fim de fevereiro
287	        if (month == Month.DECEMBER && day >= 15) {
288	            return true;
289	        }
290	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
291	            return true;
292	        }
293	
294	        return false;
295	    }
296	
297	    public static double calculateSubtotal(RoomType roomType, LocalDate checkIn, LocalDate checkOut) {
298	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
299	        double subtotal = 0.0;
300	
301	        for (int i = 0; i < nights; i++) {
302	            LocalDate nightDate = checkIn.plusDays(i);
303	            double nightlyPrice = calculateNightlyPrice(roomType.nightlyRate, nightDate);
304	            subtotal += nightlyPrice;
305	        }
306	
307	        return round(subtotal);
308	    }
309	
310	    public static double calculateDiscount(RatePlan ratePlan, double subtotal) {
311	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
312	            return round(subtotal * 0.15);
313	        }
314	        return 0.0;
315	    }
316	
317	    public static double calculateTotal(double subtotal, double discount) {
318	        return round(subtotal - discount);
319	    }
320	
321	    public static double round(double value) {
322	        BigDecimal bd = new BigDecimal(value);
323	        return bd.setScale(2, RoundingMode.HALF_EVEN).doubleValue();
324	    }
325	
326	    public static int getNights(LocalDate checkIn, LocalDate checkOut) {
327	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
328	    }
329	}

