173	    private static String formatBookingReceipt(int id, String guestName, String guestPassport,
174	                                              String guestCountry, int roomNumber, String roomType,
175	                                              LocalDate checkIn, LocalDate checkOut, int nights,
176	                                              double subtotal, double discount, double total) {
