180	        sb.append("Room: ").append(roomNumber).append(" (").append(roomType).append(")\n");
181	        sb.append("Check-in: ").append(formatDateEN(checkIn)).append(" | Check-out: ").append(formatDateEN(checkOut))
182	          .append(" | ").append(nights).append(nights == 1 ? " night" : " nights").append("\n");
183	        sb.append("Nights: ").append(formatMoneyBRL(subtotal)).append("\n");
184	        if (discount > 0) {
