 11	public class ReportController {
 12	    private final Database database;
 13	
 14	    public ReportController(Database database) {
 15	        this.database = database;
 16	    }
 17	
 18	    public void register(Javalin app) {
 19	        app.get("/reports/occupancy", this::getOccupancyReport);
 20	        app.get("/reports/revenue", this::getRevenueReport);
 21	    }
 22	
 23	    private void getOccupancyReport(io.javalin.http.Context ctx) {
 24	        try {
 25	            String dateStr = ctx.queryParam("date");
 26	            if (dateStr == null || dateStr.isEmpty()) {
 27	                ctx.status(400);
 28	                ctx.json(new java.util.HashMap<String, Object>() {{
 29	                    put("error", "INVALID_REQUEST");
 30	                    put("message", "Date parameter is required");
 31	                }});
 32	                return;
 33	            }
 34	
 35	            LocalDate date = LocalDate.parse(dateStr);
 36	            String csv = generateOccupancyReport(date);
 37	
 38	            ctx.contentType("text/csv; charset=utf-8");
 39	            ctx.result(csv);
 40	        } catch (Exception e) {
 41	            ctx.status(500);
 42	            ctx.json(new java.util.HashMap<String, Object>() {{
 43	                put("error", "INTERNAL_ERROR");
 44	                put("message", "Failed to generate report");
 45	            }});
 46	        }
 47	    }
 48	
 49	    private void getRevenueReport(io.javalin.http.Context ctx) {
 50	        try {
 51	            String monthStr = ctx.queryParam("month");
 52	            if (monthStr == null || monthStr.isEmpty()) {
 53	                ctx.status(400);
 54	                ctx.json(new java.util.HashMap<String, Object>() {{
 55	                    put("error", "INVALID_REQUEST");
 56	                    put("message", "Month parameter is required");
 57	                }});
 58	                return;
 59	            }
 60	
 61	            YearMonth month = YearMonth.parse(monthStr);
 62	            String csv = generateRevenueReport(month);
 63	
 64	            ctx.contentType("text/csv; charset=utf-8");
 65	            ctx.result(csv);
 66	        } catch (Exception e) {
 67	            ctx.status(500);
 68	            ctx.json(new java.util.HashMap<String, Object>() {{
 69	                put("error", "INTERNAL_ERROR");
 70	                put("message", "Failed to generate report");
 71	            }});
 72	        }
 73	    }
 74	
 75	    private String generateOccupancyReport(LocalDate date) throws SQLException {
 76	        StringBuilder csv = new StringBuilder();
 77	        csv.append("room,type,reservation,check_in,check_out\n");
 78	
 79	        int occupiedCount = 0;
 80	        int totalRooms = 5;
 81	
 82	        List<OccupancyRow> rows = new ArrayList<>();
 83	
 84	        try (Connection conn = database.getConnection()) {
 85	            var stmt = conn.prepareStatement("""
 86	                SELECT r.room_number, r.id, r.check_in, r.check_out, r.status
 87	                FROM reservations r
 88	                WHERE r.check_in <= ? AND r.check_out > ?
 89	                  AND r.status != ?
 90	                ORDER BY r.room_number
 91	                """);
 92	            stmt.setDate(1, java.sql.Date.valueOf(date));
 93	            stmt.setDate(2, java.sql.Date.valueOf(date));
 94	            stmt.setString(3, ReservationStatus.CANCELLED.value);
 95	
 96	            ResultSet rs = stmt.executeQuery();
 97	            Set<Integer> occupiedRooms = new HashSet<>();
 98	
 99	            while (rs.next()) {
100	                int roomNumber = rs.getInt("room_number");
101	                occupiedRooms.add(roomNumber);
102	                occupiedCount++;
103	
104	                String type = getRoomTypeName(roomNumber);
105	                rows.add(new OccupancyRow(
106	                    roomNumber,
107	                    type,
108	                    rs.getInt("id"),
109	                    rs.getDate("check_in").toLocalDate(),
110	                    rs.getDate("check_out").toLocalDate()
111	                ));
112	            }
113	        }
114	
115	        for (OccupancyRow row : rows) {
116	            csv.append(row.roomNumber).append(",")
117	               .append(row.type).append(",")
118	               .append(row.reservationId).append(",")
119	               .append(row.checkIn).append(",")
120	               .append(row.checkOut).append("\n");
121	        }
122	
123	        csv.append("total,").append(occupiedCount).append("/").append(totalRooms).append("\n");
124	
125	        return csv.toString();
126	    }
127	
128	    private String generateRevenueReport(YearMonth month) throws SQLException {
129	        StringBuilder csv = new StringBuilder();
130	        csv.append("reservation,room,check_in,check_out,status,amount\n");
131	
132	        double totalAmount = 0;
133	
134	        try (Connection conn = database.getConnection()) {
135	            var stmt = conn.prepareStatement("""
136	                SELECT r.id, r.room_number, r.check_in, r.check_out, r.status,
137	                       r.amount_paid, r.refund, r.total
138	                FROM reservations r
139	                WHERE EXTRACT(YEAR FROM r.check_in) = ?
140	                  AND EXTRACT(MONTH FROM r.check_in) = ?
141	                  AND (r.status = ? OR r.status = ? OR r.status = ? OR r.status = ?)
142	                ORDER BY r.check_in, r.id
143	                """);
144	            stmt.setInt(1, month.getYear());
145	            stmt.setInt(2, month.getMonthValue());
146	            stmt.setString(3, ReservationStatus.CONFIRMED.value);
147	            stmt.setString(4, ReservationStatus.CHECKED_IN.value);
148	            stmt.setString(5, ReservationStatus.CHECKED_OUT.value);
149	            stmt.setString(6, ReservationStatus.CANCELLED.value);
150	
151	            ResultSet rs = stmt.executeQuery();
152	
153	            while (rs.next()) {
154	                int id = rs.getInt("id");
155	                int roomNumber = rs.getInt("room_number");
156	                LocalDate checkIn = rs.getDate("check_in").toLocalDate();
157	                LocalDate checkOut = rs.getDate("check_out").toLocalDate();
158	                String status = rs.getString("status");
159	                double amountPaid = rs.getDouble("amount_paid");
160	                Double refund = rs.getObject("refund") != null ? rs.getDouble("refund") : null;
161	
162	                double netAmount = amountPaid - (refund != null ? refund : 0);
163	                totalAmount += netAmount;
164	
165	                csv.append(id).append(",")
166	                   .append(roomNumber).append(",")
167	                   .append(checkIn).append(",")
168	                   .append(checkOut).append(",")
169	                   .append(status).append(",")
170	                   .append(String.format("%.2f", netAmount)).append("\n");
171	            }
172	        }
173	
174	        csv.append("total,").append(String.format("%.2f", totalAmount)).append("\n");
175	
176	        return csv.toString();
177	    }
178	
179	    private String getRoomTypeName(int roomNumber) {
180	        return switch (roomNumber) {
181	            case 101, 102 -> "STANDARD";
182	            case 201, 202 -> "DELUXE";
183	            case 301 -> "SUITE";
184	            default -> "UNKNOWN";
185	        };
186	    }
187	
188	    static class OccupancyRow {
189	        int roomNumber;
190	        String type;
191	        int reservationId;
192	        LocalDate checkIn;
193	        LocalDate checkOut;
194	
195	        OccupancyRow(int roomNumber, String type, int reservationId, LocalDate checkIn, LocalDate checkOut) {
196	            this.roomNumber = roomNumber;
197	            this.type = type;
198	            this.reservationId = reservationId;
199	            this.checkIn = checkIn;
200	            this.checkOut = checkOut;
201	        }
202	    }
203	}
