 49	    private void getRevenueReport(io.javalin.http.Context ctx) {
 50	        try {
 51	            String monthStr = ctx.queryParam("month");
 52	            if (monthStr == null || monthStr.isEmpty()) {
 53	                ctx.status(400);
 54	                ctx.json(new java.util.HashMap<String, Object>() {{
 55	                    put("error", "INVALID_REQUEST");
 56	                    put("message", "Month parameter is required");
 57	                }});
 58	                return;
 59	            }
 60	
 61	            YearMonth month = YearMonth.parse(monthStr);
 62	            String csv = generateRevenueReport(month);
 63	
 64	            ctx.contentType("text/csv; charset=utf-8");
 65	            ctx.result(csv);
 66	        } catch (Exception e) {
 67	            ctx.status(500);
 68	            ctx.json(new java.util.HashMap<String, Object>() {{
 69	                put("error", "INTERNAL_ERROR");
 70	                put("message", "Failed to generate report");
 71	            }});
 72	        }
 73	    }
