 75	    private String generateOccupancyReport(LocalDate date) throws SQLException {
 76	        StringBuilder csv = new StringBuilder();
 77	        csv.append("room,type,reservation,check_in,check_out\n");
 78	
 79	        int occupiedCount = 0;
 80	        int totalRooms = 5;
 81	
 82	        List<OccupancyRow> rows = new ArrayList<>();
 83	
 84	        try (Connection conn = database.getConnection()) {
 85	            var stmt = conn.prepareStatement("""
 86	                SELECT r.room_number, r.id, r.check_in, r.check_out, r.status
 87	                FROM reservations r
 88	                WHERE r.check_in <= ? AND r.check_out > ?
 89	                  AND r.status != ?
 90	                ORDER BY r.room_number
 91	                """);
 92	            stmt.setDate(1, java.sql.Date.valueOf(date));
 93	            stmt.setDate(2, java.sql.Date.valueOf(date));
 94	            stmt.setString(3, ReservationStatus.CANCELLED.value);
 95	
 96	            ResultSet rs = stmt.executeQuery();
 97	            Set<Integer> occupiedRooms = new HashSet<>();
 98	
 99	            while (rs.next()) {
100	                int roomNumber = rs.getInt("room_number");
101	                occupiedRooms.add(roomNumber);
102	                occupiedCount++;
103	
104	                String type = getRoomTypeName(roomNumber);
105	                rows.add(new OccupancyRow(
106	                    roomNumber,
107	                    type,
108	                    rs.getInt("id"),
109	                    rs.getDate("check_in").toLocalDate(),
110	                    rs.getDate("check_out").toLocalDate()
111	                ));
112	            }
113	        }
114	
115	        for (OccupancyRow row : rows) {
116	            csv.append(row.roomNumber).append(",")
117	               .append(row.type).append(",")
118	               .append(row.reservationId).append(",")
119	               .append(row.checkIn).append(",")
120	               .append(row.checkOut).append("\n");
121	        }
122	
123	        csv.append("total,").append(occupiedCount).append("/").append(totalRooms).append("\n");
124	
125	        return csv.toString();
126	    }
