128	    private String generateRevenueReport(YearMonth month) throws SQLException {
129	        StringBuilder csv = new StringBuilder();
130	        csv.append("reservation,room,check_in,check_out,status,amount\n");
131	
132	        double totalAmount = 0;
133	
134	        try (Connection conn = database.getConnection()) {
135	            var stmt = conn.prepareStatement("""
136	                SELECT r.id, r.room_number, r.check_in, r.check_out, r.status,
137	                       r.amount_paid, r.refund, r.total
138	                FROM reservations r
139	                WHERE EXTRACT(YEAR FROM r.check_in) = ?
140	                  AND EXTRACT(MONTH FROM r.check_in) = ?
141	                  AND (r.status = ? OR r.status = ? OR r.status = ? OR r.status = ?)
142	                ORDER BY r.check_in, r.id
143	                """);
144	            stmt.setInt(1, month.getYear());
145	            stmt.setInt(2, month.getMonthValue());
146	            stmt.setString(3, ReservationStatus.CONFIRMED.value);
147	            stmt.setString(4, ReservationStatus.CHECKED_IN.value);
148	            stmt.setString(5, ReservationStatus.CHECKED_OUT.value);
149	            stmt.setString(6, ReservationStatus.CANCELLED.value);
150	
151	            ResultSet rs = stmt.executeQuery();
152	
153	            while (rs.next()) {
154	                int id = rs.getInt("id");
155	                int roomNumber = rs.getInt("room_number");
156	                LocalDate checkIn = rs.getDate("check_in").toLocalDate();
157	                LocalDate checkOut = rs.getDate("check_out").toLocalDate();
158	                String status = rs.getString("status");
159	                double amountPaid = rs.getDouble("amount_paid");
160	                Double refund = rs.getObject("refund") != null ? rs.getDouble("refund") : null;
161	
162	                double netAmount = amountPaid - (refund != null ? refund : 0);
163	                totalAmount += netAmount;
164	
165	                csv.append(id).append(",")
166	                   .append(roomNumber).append(",")
167	                   .append(checkIn).append(",")
168	                   .append(checkOut).append(",")
169	                   .append(status).append(",")
170	                   .append(String.format("%.2f", netAmount)).append("\n");
171	            }
172	        }
173	
174	        csv.append("total,").append(String.format("%.2f", totalAmount)).append("\n");
175	
176	        return csv.toString();
177	    }
